const { results, requestId } = $input.first().json;
if (!Array.isArray(results) || !results.length) throw new Error('Missing channel results. Open Compile catalog for the response.');
const failed = results.filter(result => result.invalid > 0 || !result.feed || result.issues.some(issue => issue.severity === 'error'));
if (failed.length) {
  const issues = failed.flatMap(result => result.issues.filter(issue => issue.severity === 'error')
    .map(issue => [result.target.channel, issue.productId || 'catalog', issue.field || issue.code].join(' / ')));
  throw new Error('Review the Compile catalog response (' + requestId + '). ' + (issues.slice(0, 8).join(', ') || 'No feed returned.'));
}
return results.map(result => ({
  json: { fileName: result.target.channel + '.' + result.target.format, feed: result.feed }
}));
